use anyhow::{Context, Result};
use minijinja::Environment;
use serde_json::Value;
use std::fs;
use std::process::Command;

use super::fonts::InstalledFonts;
use super::model;
use crate::codegen;
use crate::codegen::ios;

const GENERATED_HEADER: &str =
    "// Generated by eigin-tools — edit design/tokens.json, not this file.\n";

// Templates are co-located in src/design/ios/templates/ so the include_str! path is stable.
const TEMPLATES: &[(&str, &str)] = &[
    ("spacing", include_str!("templates/spacing.swift.jinja")),
    ("radius", include_str!("templates/radius.swift.jinja")),
    (
        "stroke_weight",
        include_str!("templates/stroke_weight.swift.jinja"),
    ),
    ("sizing", include_str!("templates/sizing.swift.jinja")),
    ("grid", include_str!("templates/grid.swift.jinja")),
    (
        "typography",
        include_str!("templates/typography.swift.jinja"),
    ),
    (
        "font_features",
        include_str!("templates/font_features.swift.jinja"),
    ),
    (
        "font_registration",
        include_str!("templates/font_registration.swift.jinja"),
    ),
    (
        "resolved_colors",
        include_str!("templates/resolved_colors.swift.jinja"),
    ),
    (
        "default_theme",
        include_str!("templates/default_theme.swift.jinja"),
    ),
    ("color_hex", include_str!("templates/color_hex.swift.jinja")),
];

pub fn load_tokens(repo_root: &str) -> Result<Value> {
    let tokens_path = format!("{repo_root}/design/tokens.json");
    let content =
        fs::read_to_string(&tokens_path).with_context(|| format!("reading {tokens_path}"))?;
    serde_json::from_str(&content).context("parsing design/tokens.json")
}

pub fn generate(repo_root: &str, tokens: &Value, fonts: Option<&InstalledFonts>) -> Result<()> {
    let output_dir = format!("{repo_root}/src/eigin_ios/Sources/Core/Design/Generated");

    let mut env = Environment::new();
    ios::install_filters(&mut env);
    for (name, source) in TEMPLATES {
        env.add_template(name, source)
            .with_context(|| format!("registering template '{name}'"))?;
    }

    // Spacing
    let scale = model::parse_spacing(tokens)?;
    render_and_write(
        &env,
        "spacing",
        minijinja::context!(header => GENERATED_HEADER, scale => scale),
        &output_dir,
        "Spacing.swift",
    )?;

    // Radius
    let scale = model::parse_radius(tokens)?;
    render_and_write(
        &env,
        "radius",
        minijinja::context!(header => GENERATED_HEADER, scale => scale),
        &output_dir,
        "Radius.swift",
    )?;

    // StrokeWeight
    let scale = model::parse_stroke_weight(tokens)?;
    render_and_write(
        &env,
        "stroke_weight",
        minijinja::context!(header => GENERATED_HEADER, scale => scale),
        &output_dir,
        "StrokeWeight.swift",
    )?;

    // Sizing
    let scale = model::parse_sizing(tokens)?;
    let sizing_body = scale.render_body();
    let sizing_output = format!(
        "{GENERATED_HEADER}import SwiftUI\n\n/// Component sizing dimensions. Generated from design/tokens.json.\nenum Sizing {{\n{sizing_body}}}\n"
    );
    codegen::write_file(&output_dir, "Sizing.swift", &sizing_output)?;

    // Grid
    let scale = model::parse_grid(tokens)?;
    render_and_write(
        &env,
        "grid",
        minijinja::context!(header => GENERATED_HEADER, scale => scale),
        &output_dir,
        "Grid.swift",
    )?;

    // FontFeatures (static helper for custom font OpenType features)
    let font_features = env
        .get_template("font_features")
        .context("getting font_features")?;
    let font_features_output = font_features
        .render(minijinja::context!(header => GENERATED_HEADER))
        .context("rendering font_features")?;
    codegen::write_file(&output_dir, "FontFeatures.swift", &font_features_output)?;

    // Typography
    let scale = model::parse_typography(tokens, fonts)?;
    render_and_write(
        &env,
        "typography",
        minijinja::context!(header => GENERATED_HEADER, scale => scale),
        &output_dir,
        "Typography.swift",
    )?;

    // FontRegistration
    let info = model::build_font_registration(fonts);
    render_and_write(
        &env,
        "font_registration",
        minijinja::context!(header => GENERATED_HEADER, info => info),
        &output_dir,
        "FontRegistration.swift",
    )?;

    // ResolvedColors
    let tree = model::parse_color_tree(tokens)?;
    let struct_body = tree.render_struct_body();
    let rc_output = format!(
        "{GENERATED_HEADER}import SwiftUI\n\n/// Resolved color set for a given theme and color scheme. Generated from design/tokens.json.\nstruct ResolvedColors {{\n{struct_body}}}\n"
    );
    codegen::write_file(&output_dir, "ResolvedColors.swift", &rc_output)?;

    // DefaultTheme
    let light_body = tree.render_init_body("light", 3);
    let dark_body = tree.render_init_body("dark", 3);
    let dt_output = format!(
        "{GENERATED_HEADER}import SwiftUI\n\n/// Default Eigin theme. Generated from design/tokens.json.\nstruct DefaultTheme: Theme {{\n    var name: String {{ Localized.Ui.defaultLabel }}\n    let id = \"default\"\n\n    func colors(for colorScheme: ColorScheme) -> ResolvedColors {{\n        switch colorScheme {{\n        case .light:\n            return ResolvedColors(\n                {light_body}            )\n        case .dark:\n            return ResolvedColors(\n                {dark_body}            )\n        @unknown default:\n            return colors(for: .light)\n        }}\n    }}\n}}\n"
    );
    codegen::write_file(&output_dir, "DefaultTheme.swift", &dt_output)?;

    // Color+Hex (static template)
    let hex = env.get_template("color_hex").context("getting color_hex")?;
    let hex_output = hex
        .render(minijinja::context!(header => GENERATED_HEADER))
        .context("rendering color_hex")?;
    codegen::write_file(&output_dir, "Color+Hex.swift", &hex_output)?;

    // Format
    let status = Command::new("swiftformat")
        .arg(&output_dir)
        .status()
        .context("running swiftformat on Generated/")?;
    if !status.success() {
        anyhow::bail!("swiftformat failed on {output_dir}");
    }

    Ok(())
}

fn render_and_write(
    env: &Environment,
    name: &str,
    ctx: minijinja::Value,
    output_dir: &str,
    filename: &str,
) -> Result<()> {
    let content =
        codegen::render(env, name, ctx).with_context(|| format!("rendering {filename}"))?;
    codegen::write_file(output_dir, filename, &content)
}
